use femto_kosync::DocumentId;
use std::io::{Cursor, Read, Seek, SeekFrom, Write};

// Generated by KOReader util.partialMD5 and koreader-base ffi/sha2.lua.
#[test]
fn official_lua_vectors_cover_sample_boundaries_and_sparse_last_sample() {
    for (size, expected) in [
        (0, "d41d8cd98f00b204e9800998ecf8427e"),
        (1, "93b885adfe0da089cdf634904fd59f71"),
        (1023, "3623584153f95f5919cd18072c6a8c53"),
        (1024, "ba2ef37aad8769abdb592185fc8bfb35"),
        (1025, "3d963d43dc1782068f425f5247519fda"),
        (4097, "5daf75cf9d124da4c0215387600b1dae"),
        (17000, "d2a72a2eeb39d56265b426030ca7d982"),
    ] {
        let mut source = Cursor::new(
            (0..size)
                .map(|i| ((i * 37 + i / 257) % 256) as u8)
                .collect::<Vec<_>>(),
        );
        source.set_position(42);
        assert_eq!(DocumentId::sampled(&mut source).unwrap().as_str(), expected);
        assert_eq!(source.position(), 42);
    }
    let mut sparse = tempfile::tempfile().unwrap();
    sparse.seek(SeekFrom::Start(1_073_741_824)).unwrap();
    sparse.write_all(b"femto").unwrap();
    assert_eq!(
        DocumentId::sampled(&mut sparse).unwrap().as_str(),
        "c812fda4ebcdc177fd0594b564d7e2e2"
    );
    assert_eq!(
        DocumentId::filename("Café.epub").unwrap().as_str(),
        "e2c3111145393dc5349289bff4ad73a4"
    );
}
struct ShortReads(Cursor<Vec<u8>>);
impl Read for ShortReads {
    fn read(&mut self, bytes: &mut [u8]) -> std::io::Result<usize> {
        let len = bytes.len().min(7);
        self.0.read(&mut bytes[..len])
    }
}
impl Seek for ShortReads {
    fn seek(&mut self, pos: SeekFrom) -> std::io::Result<u64> {
        self.0.seek(pos)
    }
}
#[test]
fn short_reads_do_not_change_checksum() {
    let data = (0..17000)
        .map(|i| ((i * 37 + i / 257) % 256) as u8)
        .collect();
    let mut source = ShortReads(Cursor::new(data));
    assert_eq!(
        DocumentId::sampled(&mut source).unwrap().as_str(),
        "d2a72a2eeb39d56265b426030ca7d982"
    );
}
